mapper.select:
SELECT EXISTS(
    SELECT 1 FROM tbl_dim_ticket WHERE ticket_id = #{ticketId} AND project_id = #{projectId}
)

SELECT EXISTS(
    SELECT 1
    FROM tbl_fact_pull_request pr
    WHERE pr.ticket_id = #{ticketId}
      AND pr.repository_id = #{repositoryId}
    UNION
    SELECT 1
    FROM tbl_fact_commit c
    WHERE c.ticket_id = #{ticketId}
      AND c.repository_id = #{repositoryId}
)

SELECT ticket_id, external_ticket_key, title
FROM tbl_dim_ticket t
WHERE t.project_id = #{projectId}

    AND (
        EXISTS (
            SELECT 1 FROM tbl_fact_pull_request pr
            WHERE pr.ticket_id = t.ticket_id AND pr.repository_id = #{repositoryId}
        )
        OR EXISTS (
            SELECT 1 FROM tbl_fact_commit c
            WHERE c.ticket_id = t.ticket_id AND c.repository_id = #{repositoryId}
        )
    )

ORDER BY t.external_ticket_key ASC
